import os
from collections import defaultdict
from pathlib import Path

import matplotlib.pyplot as plt
import numpy as np
import seaborn as sns
from scipy import stats


def load_experiment_results(results_dir):
    """
    Load all experiment results from the specified directory structure.

    Args:
        results_dir: Path to the results directory

    Returns:
        dict: Dictionary with run_name as keys and list of arrays as values
    """
    results = defaultdict(list)
    results_path = Path(results_dir)

    if not results_path.exists():
        raise FileNotFoundError(f"Results directory {results_dir} not found")

    # Iterate through all run directories
    for run_dir in results_path.iterdir():
        if run_dir.is_dir():
            run_name = run_dir.name

            # Load all .npy files in this run directory
            for npy_file in run_dir.glob("*.npy"):
                try:
                    data = np.load(npy_file)
                    results[run_name].append(data)
                    print(f"Loaded {npy_file} with shape {data.shape}")
                except Exception as e:
                    print(f"Error loading {npy_file}: {e}")

    return dict(results)


def pad_sequences(sequences, pad_value=np.nan):
    """
    Pad sequences to the same length with specified value.

    Args:
        sequences: List of 1D numpy arrays
        pad_value: Value to use for padding (default: np.nan)

    Returns:
        numpy.ndarray: 2D array with padded sequences
    """
    if not sequences:
        return np.array([])

    max_length = max(len(seq) for seq in sequences)
    padded = np.full((len(sequences), max_length), pad_value)

    for i, seq in enumerate(sequences):
        padded[i, : len(seq)] = seq

    return padded


def compute_confidence_intervals(data, confidence=0.95):
    """
    Compute confidence intervals for the data.

    Args:
        data: 2D array where each row is a run and columns are time steps
        confidence: Confidence level (default: 0.95)

    Returns:
        tuple: (mean, lower_bound, upper_bound, std)
    """
    # Handle NaN values by computing statistics only on valid data
    import warnings

    with warnings.catch_warnings():
        warnings.simplefilter("ignore", category=RuntimeWarning)

        mean = np.nanmean(data, axis=0)
        std = np.nanstd(data, axis=0)
        n_valid = np.sum(~np.isnan(data), axis=0)

        # Compute confidence intervals using t-distribution
        alpha = 1 - confidence

        # Initialize bounds
        lower_bound = np.full_like(mean, np.nan)
        upper_bound = np.full_like(mean, np.nan)

        # Only compute CI where we have at least 2 valid samples
        valid_mask = n_valid >= 2

        if np.any(valid_mask):
            # Use t-distribution for small samples, normal for large samples
            t_scores = stats.t.ppf(1 - alpha / 2, n_valid[valid_mask] - 1)
            margin_error = t_scores * (std[valid_mask] / np.sqrt(n_valid[valid_mask]))

            lower_bound[valid_mask] = mean[valid_mask] - margin_error
            upper_bound[valid_mask] = mean[valid_mask] + margin_error

    return mean, lower_bound, upper_bound, std


def plot_experiment_results(
    results, confidence=0.95, step_size=1000, figsize=(12, 8), save_path=None
):
    """
    Plot experiment results with confidence intervals.

    Args:
        results: Dictionary with run_name as keys and list of arrays as values
        confidence: Confidence level for intervals
        step_size: Steps between measurements (for x-axis labeling)
        figsize: Figure size tuple
        save_path: Path to save the plot (optional)
    """
    plt.figure(figsize=figsize)

    # Set up colors for different runs
    colors = plt.cm.Set1(np.linspace(0, 1, len(results)))

    for i, (run_name, run_data) in enumerate(results.items()):
        if not run_data:
            print(f"No data found for run: {run_name}")
            continue

        # Pad sequences to same length
        padded_data = pad_sequences(run_data)

        # Compute statistics
        mean, lower, upper, std = compute_confidence_intervals(padded_data, confidence)

        # Create x-axis (time steps)
        x_axis = np.arange(len(mean)) * step_size

        # Plot mean line
        color = colors[i]
        plt.plot(
            x_axis,
            mean,
            label=f"{run_name} (n={len(run_data)})",
            color=color,
            linewidth=2,
        )

        # Plot confidence interval
        valid_mask = ~np.isnan(mean)
        if np.any(valid_mask):
            plt.fill_between(
                x_axis[valid_mask],
                lower[valid_mask],
                upper[valid_mask],
                alpha=0.3,
                color=color,
            )

        print(
            f"Run {run_name}: {len(run_data)} experiments, "
            f"max length: {padded_data.shape[1]} steps"
        )

    plt.xlabel(f"Training Steps")
    plt.ylabel("Episode Length")
    plt.title(f"Episode Length Over Time ({confidence*100:.0f}% Confidence Intervals)")
    plt.legend(bbox_to_anchor=(1.05, 1), loc="upper left")
    plt.grid(True, alpha=0.3)
    plt.tight_layout()

    if save_path:
        plt.savefig(save_path, dpi=300, bbox_inches="tight")
        print(f"Plot saved to {save_path}")

    plt.show()


def plot_final_performance_comparison(results, figsize=(10, 6), save_path=None):
    """
    Create a box plot comparing final performance across runs.

    Args:
        results: Dictionary with run_name as keys and list of arrays as values
        figsize: Figure size tuple
        save_path: Path to save the plot (optional)
    """
    final_scores = []
    run_names = []

    for run_name, run_data in results.items():
        for data in run_data:
            if len(data) > 0:
                final_scores.append(data[-1])  # Last recorded episode length
                run_names.append(run_name)

    if not final_scores:
        print("No final scores found to plot")
        return

    plt.figure(figsize=figsize)

    # Create box plot
    unique_runs = list(results.keys())
    final_by_run = [[] for _ in unique_runs]

    for score, run in zip(final_scores, run_names):
        run_idx = unique_runs.index(run)
        final_by_run[run_idx].append(score)

    plt.boxplot(final_by_run, labels=unique_runs)
    plt.ylabel("Final Episode Length")
    plt.title("Final Performance Comparison Across Runs")
    plt.xticks(rotation=45)
    plt.grid(True, alpha=0.3)
    plt.tight_layout()

    if save_path:
        plt.savefig(save_path, dpi=300, bbox_inches="tight")
        print(f"Box plot saved to {save_path}")

    plt.show()


